import {
    Table,
    ReferenceColumn,
    UserRolesColumn,
    BooleanColumn,
    DomainIdColumn,
    StringColumn,
    DomainPathColumn,
    IntegerColumn,
    TranslatedFieldColumn,
} from '../../db'

export const sys_ui_application = Table({
    allowWebServiceAccess: true,
    attributes: {
        ref_ac_columns: 'name',
        ref_ac_columns_search: true,
        ref_auto_completer: 'AJAXTableCompleter',
        update_synch: true,
    },
    audit: true,
    display: 'name',
    extends: 'sys_metadata',
    label: 'Application Menu',
    name: 'sys_ui_application',
    schema: {
        sys_overrides: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Application being overridden by the current record',
                    label: 'Overrides',
                    plural: 'Overrides',
                },
            ],
            referenceTable: 'sys_app_application',
        }),
        roles: UserRolesColumn({
            array: true,
            attributes: {
                no_truncate: true,
                record_watcher_blacklist: true,
            },
            label: [
                {
                    hint: 'Who can use this application',
                    label: 'Roles',
                    plural: 'Roles',
                },
            ],
        }),
        active: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Application in use?',
                    label: 'Active',
                    plural: 'Active',
                },
            ],
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which the script belongs',
                    label: 'Domain',
                    plural: 'Domains',
                },
            ],
        }),
        hint: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
                no_truncate: true,
            },
            label: 'Hint',
            maxLength: 255,
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
        }),
        order: IntegerColumn({
            label: 'Order',
        }),
        name: TranslatedFieldColumn({
            label: [
                {
                    hint: 'Name appearing in Menu (translated)',
                    label: 'Name',
                    plural: 'Names',
                },
            ],
            mandatory: true,
        }),
    },
    textIndex: true,
})
